mapper.insert:
/* kr.or.kids.domain.cm.common.mapper.insertFileUld */
INSERT INTO kids_own.tb_cm_m_file_uld (
      pst_sn
    , atch_file_id
    , uld_task_se_cd
    , file_se_cd
    , ptcp_inst_sn
    , del_yn
    , rgtr_id
    , reg_dt
    , mdfr_id
    , mdfcn_dt
) VALUES (
      #{pstSn}
    , #{atchFileId}
    , #{uldTaskSeCd}
    , #{fileSeCd}
    , #{ptcpInstSn}
    , #{delYn}
    , COALESCE(#{rgtrId}, '관리자')
    , NOW()
    , COALESCE(#{rgtrId}, '관리자')
    , NOW()
)

mapper.select:
SELECT /* kr.or.kids.domain.cm.common.mapper.selectFileUldList */ pst_sn , atch_file_id , uld_task_se_cd , file_se_cd , ptcp_inst_sn , del_yn , rgtr_id , reg_dt , mdfr_id , mdfcn_dt FROM kids_own.tb_cm_m_file_uld WHERE pst_sn = #{pstSn}
AND uld_task_se_cd = #{uldTaskSeCd}
AND file_se_cd = #{fileSeCd}
AND del_yn = 'N'

mapper.update:
/* kr.or.kids.domain.cm.common.mapper.deleteFileUld */
UPDATE kids_own.tb_cm_m_file_uld
   SET del_yn = 'Y'
     , mdfr_id = COALESCE(#{mdfrId}, '관리자')
     , mdfcn_dt = NOW()
 WHERE pst_sn = #{pstSn}
   AND atch_file_id = #{atchFileId}

mapper.insert:
/* kr.or.kids.domain.cm.common.mapper.insertFileGroup */
INSERT INTO kids_own.tb_ca_e_file_group_trsm (
      atch_file_group_id
    , task_se_cd
    , task_se_trgt_id
    , use_yn
    , reg_dt
    , rgtr_id
    , mdfcn_dt
    , mdfr_id
) VALUES (
      #{atchFileGroupId}
    , #{taskSeCd}
    , #{taskSeTrgtId}
    , 'Y'
    , NOW()
    , COALESCE(#{rgtrId}, '관리자')
    , NOW()
    , COALESCE(#{rgtrId}, '관리자')
)

mapper.update:
/* kr.or.kids.domain.cm.common.mapper.deleteFileGroup */
UPDATE kids_own.tb_ca_e_file_group_trsm
   SET use_yn = 'N'
     , mdfcn_dt = NOW()
     , mdfr_id = COALESCE(#{mdfrId}, '관리자')
 WHERE atch_file_group_id = #{atchFileGroupId}

mapper.delete:
/* kr.or.kids.domain.cm.common.mapper.hardDeleteFileGroup - local only */
DELETE FROM kids_own.tb_ca_e_file_group_trsm
 WHERE atch_file_group_id = #{atchFileGroupId}

mapper.insert:
/* kr.or.kids.domain.cm.common.mapper.insertFileBatch */
INSERT INTO kids_own.tb_ca_e_file_trsm (
      atch_file_id
    , atch_file_group_id
    , file_seq
    , file_strg_path_dsctn
    , prvc_incl_yn
    , file_nm
    , file_extn_nm
    , file_cn
    , file_sz
    , crt_dt
    , use_yn
    , reg_dt
    , rgtr_id
    , mdfcn_dt
    , mdfr_id
    , srvr_file_nm
)
VALUES

    (
      #{item.atchFileId}
    , #{item.atchFileGroupId}
    , #{item.fileSeq}
    , #{item.fileStrgPathDsctn}
    , #{item.prvcInclYn}
    , #{item.fileNm}
    , #{item.fileExtnNm}
    , #{item.fileCn}
    , #{item.fileSz}
    , to_char(NOW(), 'YYYYMMDDHH24MISS')
    , 'Y'
    , NOW()
    , COALESCE(#{item.rgtrId}, '관리자')
    , NOW()
    , COALESCE(#{item.rgtrId}, '관리자')
    , #{item.srvrFileNm}
    )

mapper.update:
/* kr.or.kids.domain.cm.common.mapper.deleteFile */
UPDATE kids_own.tb_ca_e_file_trsm
   SET use_yn = 'N'
     , mdfcn_dt = NOW()
     , mdfr_id = COALESCE(#{mdfrId}, '관리자')
 WHERE atch_file_group_id = #{atchFileGroupId}

/* kr.or.kids.domain.cm.common.mapper.deleteFileById */
UPDATE kids_own.tb_ca_e_file_trsm
   SET use_yn = 'N'
     , mdfcn_dt = NOW()
     , mdfr_id = COALESCE(#{mdfrId}, '관리자')
 WHERE atch_file_id = #{atchFileId}

mapper.delete:
/* kr.or.kids.domain.cm.common.mapper.hardDeleteFile - local only */
DELETE FROM kids_own.tb_ca_e_file_trsm
 WHERE atch_file_group_id = #{atchFileGroupId}

/* kr.or.kids.domain.cm.common.mapper.hardDeleteFileById - local only */
DELETE FROM kids_own.tb_ca_e_file_trsm
 WHERE atch_file_id = #{atchFileId}
